// === Single consolidated Zendesk ticket update ===
//
// This node replaces what used to be FIVE sequential PUTs to the same ticket:
//   1. Set language           - language custom field
//   2. Reply ... solved12/13  - public comment + category custom field
//   3. Tag as automation replied
//   4. Set status to solved   - custom_status_id
//   5. Reply ... solved11/15  - automation label custom field
//
// They were split because n8n's dot-notation body params
// (ticket.custom_fields.id / .value) can only express ONE custom field per
// request. Building the object here and sending it as raw JSON lifts that
// limit, so everything goes in one call.
//
// Zendesk enforces 30 ticket updates per 10 minutes PER TICKET. A first-message
// plus second-message conversation used to cost 10 PUTs; it now costs 2.

const input = $('When Executed by Another Workflow').first().json;
const cfg = $('Get Project Config').first().json || {};
const live = ($('Get ticket status').first().json || {}).ticket || {};

// --- comment body ----------------------------------------------------------
// Both branches converge here. isTranslated tells us which upstream node ran;
// the branch guarantees it has executed, so the reference is safe.
const isTranslated = input.isTranslated === true;
const htmlBody = isTranslated
  ? $('Translate macro to local language').first().json.output[0].content[0].text.translatedComment
  : $('Generate customer reply with macro8').first().json.result.ticket.comment.html_body;

// --- custom fields ---------------------------------------------------------
const customFields = [];
function addField(id, value) {
  const numericId = Number(id);
  if (!Number.isFinite(numericId) || numericId <= 0) return;
  if (value === undefined || value === null || value === '') return;
  customFields.push({ id: numericId, value: value });
}

addField(cfg.ticket_field_language_id, input.originalLanguage);
addField(input.ticketCustomFieldID, input.ticketCustomFieldValue);
addField(input.automationCustomFieldID, input.automationCustomFieldValue);

// --- Rejection Complaint (record-based case 2) -----------------------------
// Derived centrally from the macro that was applied, rather than being set by
// each caller. Verified 2026-09 against the refund flow: of ~24 Edit Fields
// nodes that feed this sub-workflow, exactly ONE (Edit Fields32) passes the
// rejection macro, so exactly one path yields "yes".
//
// Deriving it here means a macro added later defaults to "no" without anyone
// remembering to wire it up, and there is a single place to audit.
const appliedMacro = String(input.macroID || '').trim();
const rejectionMacro = String(cfg.refund_macro_rejection_id || '').trim();
const rejectionMacroAlt = String(cfg.refund_macro_rejection_alt_id || '').trim();

const isRejection = appliedMacro !== '' && (
  (rejectionMacro !== '' && appliedMacro === rejectionMacro) ||
  (rejectionMacroAlt !== '' && appliedMacro === rejectionMacroAlt)
);

// STICKY. Once a ticket carries "yes" it keeps it. This sub-workflow runs on
// every automated reply, including 2nd-message replies (thanks, refund
// confirmation, a refund granted on a second attempt). Without this, a thank-you
// after a rejection would flip the ticket to "no" and erase the record case 2
// looks for. The field is still sent on every call, so the required-to-solve
// check always passes. The current value comes from the Get ticket status read
// above - no extra API call.
const rcFieldId = Number(cfg.ticket_field_rejection_complaint);
const liveFields = Array.isArray(live.custom_fields) ? live.custom_fields : [];
const rcCurrent = liveFields.find(f => Number(f.id) === rcFieldId);
// Option values from cs_project_config.rejection_complaint_value_yes / _no.
// Empty = yes / no. A brand whose Language field already uses the tag "no"
// (Norwegian) needs a different value, since Zendesk dropdown tags are unique.
const rcYes = String(cfg.rejection_complaint_value_yes || 'yes');
const rcNo = String(cfg.rejection_complaint_value_no || 'no');
const rcWasYes = !!rcCurrent && rcCurrent.value === rcYes;
const rejectionComplaint = (isRejection || rcWasYes) ? rcYes : rcNo;

addField(cfg.ticket_field_rejection_complaint, rejectionComplaint);

// --- tags ------------------------------------------------------------------
// A single-ticket PUT REPLACES the tag array, so the live tags read moments ago
// by Get ticket status are merged in. (ticket.additional_tags is silently
// discarded on this endpoint - 200 response, no tag event in the audit.)
const tags = Array.isArray(live.tags) ? live.tags.slice() : [];
if (tags.indexOf('automation_replied') === -1) tags.push('automation_replied');

// --- assemble --------------------------------------------------------------
const ticket = {
  comment: { public: input.publicComment, html_body: htmlBody },
  tags: tags
};

if (customFields.length > 0) ticket.custom_fields = customFields;

const statusId = Number(input.ticketCustomStatusID);
if (Number.isFinite(statusId) && statusId > 0) ticket.custom_status_id = statusId;

return [{
  json: {
    ticket_id: input.ticketID,
    zendesk_domain: input.zendeskDomain,
    is_translated: isTranslated,
    applied_macro: appliedMacro,
    rejection_complaint: rejectionComplaint,
    rejection_complaint_was_yes: rcWasYes,
    custom_fields_sent: customFields,
    tags_sent: tags,
    zendesk_body: { ticket: ticket }
  }
}];
